SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS=0;
DROP TABLE IF EXISTS `hs_code_catalog`;
CREATE TABLE `hs_code_catalog` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `section_id` smallint(5) unsigned NOT NULL,
  `section_name` text NOT NULL,
  `chapter_code` varchar(2) NOT NULL,
  `chapter_name` text NOT NULL,
  `heading_code` varchar(4) NOT NULL,
  `heading_name` text NOT NULL,
  `hs_code` varchar(6) NOT NULL,
  `description` text NOT NULL,
  `parent_code` varchar(6) DEFAULT NULL,
  `level` tinyint(3) unsigned NOT NULL DEFAULT 6,
  `version` varchar(20) NOT NULL DEFAULT 'HS 2022',
  PRIMARY KEY (`id`),
  UNIQUE KEY `hs_code_catalog_hs_code_unique` (`hs_code`),
  KEY `hs_code_catalog_chapter_code_index` (`chapter_code`),
  KEY `hs_code_catalog_heading_code_index` (`heading_code`)
) ENGINE=InnoDB AUTO_INCREMENT=5613 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
SET FOREIGN_KEY_CHECKS=1;
